      beauty:`<h4>美の核</h4><p>凛とした品格と知性。流行に流されすぎず、長く愛せる定番・上質な仕立てが似合います。年齢を味方につける「育つ美」の星。</p>
<h4>似合う色・素材</h4><p>ネイビー・チャコール・キャメル・ボルドー。ウール・ツイード・上質レザー。きちんと感のある仕立てが武器。</p>
<h4>磨くべきポイント</h4><p>骨格（山羊座の支配領域）・関節・歯。姿勢の良さと白い歯がそのまま品格に。シンプルで強いシルエットの服を選んで。</p>`,
      future:`<h4>これからの流れ</h4><p>積み重ねが「実」になる時期。これまで地道に続けてきたことが社会的評価・立場の向上として返ってきます。焦らず、自分の計画を信じて続けて。</p>
<h4>訪れる転機</h4><p>年末年始・新年の節目に重要なポジション・契約・昇進の話が。目上の人からの引き立てで道が開きます。</p>
<h4>メッセージ</h4><p>あなたが今いる場所より、一段上を「すでにそこにいる自分」として振る舞って。</p>`,
