      lifepath: '運命数6：人生のテーマは「家族と責任」。守るべきものができたとき本領を発揮します。',
      soul: '魂数6：心の奥で求めているのは「愛し愛されること」。孤独な環境では魂が枯れます。',
      personality: '人格数6：周囲からは「温かく面倒見が良い」と見られます。家族・チームの母性的存在。',
      maturity: '成熟数6：人生後半は「育てる役割」がテーマ。子育て・部下育成・コミュニティ運営で輝きます。'
